    [4430]={name="Ethereal Talisman",quality=2,ilvl=43,reqLevel=34,sourceType="quest_reward",instructions="Reward from the quest 'The Crown of Will'. Starts with Melisara in Alterac Mountains. Objective: Kill 14 Crushridge Maulers for Melisara in Tarren Mill.",zone="Hillsbrad Foothills",questName="The Crown of Will",lore="All that remains is to deliver the Crown of Will to Sharlindra in the Undercity. She will see that it is delivered to Lady Sylvanas."},
