    [16577]={name="Warlord's Mail Armor",quality=4,ilvl=74,reqLevel=60,sourceType="vendor",instructions="Bought from First Sergeant Hola'mahi - costs tokens or reputation.",npc="First Sergeant Hola'mahi"},
    [16623]={name="Opaline Medallion",quality=2,ilvl=57,sourceType="quest_reward",instructions="Reward from the quest 'Wildkin of Elune'. Pick it over the other reward choices. Starts with Erelas Ambersky in Darnassus. Objective: Speak with Arch Druid Fandral Staghelm in Darnassus.",zone="Winterspring",questName="Wildkin of Elune",lore="That's fascinating! I have always wondered about the truth... Well, you must share this knowledge, definitely! Go to Arch Druid Fandral Staghelm right away -- you'll find him in Darnassus, in the Cenarion Circle."},
    [16659]={name="Deftkin Belt",quality=2,ilvl=27,sourceType="quest_reward",instructions="Reward from the quest 'Je'neu of the Earthen Ring'. Pick it over the other reward choices. Starts with Mastok Wrilehiss in Ashenvale. Objective: Bring the Befouled Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.",zone="Ashenvale",questName="Je'neu of the Earthen Ring",lore="The Earthen Ring is a shamanistic group dedicated to studying and preserving the elements. They have forgotten more about crazy old gods, ancient legends and lore than most scholars will ever know."},
    [16660]={name="Driftmire Shield",quality=2,ilvl=27,sourceType="quest_reward",instructions="Reward from the quest 'Je'neu of the Earthen Ring'. Pick it over the other reward choices. Starts with Mastok Wrilehiss in Ashenvale. Objective: Bring the Befouled Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.",zone="Ashenvale",questName="Je'neu of the Earthen Ring",lore="The Earthen Ring is a shamanistic group dedicated to studying and preserving the elements. They have forgotten more about crazy old gods, ancient legends and lore than most scholars will ever know."},
    [16661]={name="Soft Willow Cape",quality=2,ilvl=27,sourceType="quest_reward",instructions="Reward from the quest 'Je'neu of the Earthen Ring'. Pick it over the other reward choices. Starts with Mastok Wrilehiss in Ashenvale. Objective: Bring the Befouled Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.",zone="Ashenvale",questName="Je'neu of the Earthen Ring",lore="The Earthen Ring is a shamanistic group dedicated to studying and preserving the elements. They have forgotten more about crazy old gods, ancient legends and lore than most scholars will ever know."},
