    [23005]={name="Totem of Flowing Water",quality=4,ilvl=83,reqLevel=60,sourceType="boss_drop",instructions="Drops from Noth the Plaguebringer.",zone="Naxxramas",npc="Noth the Plaguebringer",lore="A necromancer of the Plague Quarter, promoted for his skill at raising what he had just finished killing."},
    [23018]={name="Signet of the Fallen Defender",quality=4,ilvl=83,reqLevel=60,sourceType="boss_drop",instructions="Drops from Instructor Razuvious.",zone="Naxxramas",npc="Instructor Razuvious",lore="A death knight who trains the Scourge's new officers. He is too strong for his own students to touch, which is exactly the point of the lesson."},
